function( $post_id, $post ) {
    if ( ! isset( $_POST['az_gioi_thieu_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['az_gioi_thieu_nonce'] ) ), 'az_gioi_thieu_save' ) ) {
        return;
    }
    if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) {
        return;
    }
    if ( ! current_user_can( 'edit_post', $post_id ) ) {
        return;
    }

    $data = array(
        'intro' => array(
            'title' => sanitize_text_field( wp_unslash( $_POST['az_gt_intro_title'] ?? '' ) ),
            'image' => esc_url_raw( wp_unslash( $_POST['az_gt_intro_image'] ?? '' ) ),
            'paragraphs' => array_values( array_filter( array_map( 'az_gioi_thieu_clean_paragraph', wp_unslash( $_POST['az_gt_intro_paragraphs'] ?? array() ) ) ) ),
        ),
        'advantages' => array(
            'title' => sanitize_text_field( wp_unslash( $_POST['az_gt_advantages_title'] ?? '' ) ),
            'image' => esc_url_raw( wp_unslash( $_POST['az_gt_advantages_image'] ?? '' ) ),
            'items' => array_values( array_filter( array_map( 'sanitize_text_field', wp_unslash( $_POST['az_gt_advantage_items'] ?? array() ) ) ) ),
        ),
        'vision' => array(
            'title' => sanitize_text_field( wp_unslash( $_POST['az_gt_vision_title'] ?? '' ) ),
            'image' => esc_url_raw( wp_unslash( $_POST['az_gt_vision_image'] ?? '' ) ),
            'captions' => array_values( array_filter( array_map( 'sanitize_textarea_field', wp_unslash( $_POST['az_gt_vision_captions'] ?? array() ) ) ) ),
        ),
        'mission' => array(
            'title' => sanitize_text_field( wp_unslash( $_POST['az_gt_mission_title'] ?? '' ) ),
            'description' => sanitize_textarea_field( wp_unslash( $_POST['az_gt_mission_description'] ?? '' ) ),
            'items' => az_gt_rows( 'az_gt_mission', array( 'icon' => 'url', 'icon_text' => 'text', 'title_item' => 'text', 'text' => 'textarea' ) ),
        ),
        'core_values' => array(
            'title' => sanitize_text_field( wp_unslash( $_POST['az_gt_core_values_title'] ?? '' ) ),
            'image' => esc_url_raw( wp_unslash( $_POST['az_gt_core_values_image'] ?? '' ) ),
            'items' => array_values( array_filter( array_map( 'sanitize_text_field', wp_unslash( $_POST['az_gt_core_value_items'] ?? array() ) ) ) ),
        ),
        'cooperation' => array(
            'title' => sanitize_text_field( wp_unslash( $_POST['az_gt_cooperation_title'] ?? '' ) ),
            'paragraphs' => array_values( array_filter( array_map( 'sanitize_textarea_field', wp_unslash( $_POST['az_gt_cooperation_paragraphs'] ?? array() ) ) ) ),
            'background_image' => esc_url_raw( wp_unslash( $_POST['az_gt_cooperation_background_image'] ?? '' ) ),
            'name_placeholder' => sanitize_text_field( wp_unslash( $_POST['az_gt_cooperation_name_placeholder'] ?? '' ) ),
            'phone_placeholder' => sanitize_text_field( wp_unslash( $_POST['az_gt_cooperation_phone_placeholder'] ?? '' ) ),
            'button_text' => sanitize_text_field( wp_unslash( $_POST['az_gt_cooperation_button_text'] ?? '' ) ),
        ),
    );

    foreach ( $data['mission']['items'] as $index => $item ) {
        $data['mission']['items'][ $index ]['title'] = $item['title_item'] ?? '';
        unset( $data['mission']['items'][ $index ]['title_item'] );
    }

    $data['vision']['caption'] = $data['vision']['captions'][0] ?? '';
    $data['cooperation']['text'] = $data['cooperation']['paragraphs'][0] ?? '';

    update_post_meta( $post_id, '_az_gioi_thieu_data', wp_json_encode( $data, JSON_UNESCAPED_UNICODE ) );
}
